&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;10&quot; data-list-defn-props=&quot;{&amp;quot;335551500&amp;quot;:0,&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;11&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Comfort working with SQL databases, Git, Docker-based workflows, and modern CI/CD pipelines.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:60}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;10&quot; data-list-defn-props=&quot;{&amp;quot;335551500&amp;quot;:0,&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;12&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Practical understanding of &lt;strong&gt;AI-assisted engineering tools&lt;/strong&gt;, and the judgment to use them responsibly with privacy, security, and quality in mind.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:60}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;10&quot; data-list-defn-props=&quot;{&amp;quot;335551500&amp;quot;:0,&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;13&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Clear communication skills, a collaborative mindset, and the confidence to contribute ideas in technical discussions and code reviews.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:60}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;span data-contrast=&quot;none&quot;&gt;It would be great if you had these too, but&amp;nbsp;we’ll&amp;nbsp;support you if you&amp;nbsp;don’t:&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;201341983&amp;quot;:0,&amp;quot;335551550&amp;quot;:6,&amp;quot;335551620&amp;quot;:6,&amp;quot;335559738&amp;quot;:300,&amp;quot;335559739&amp;quot;:300,&amp;quot;335559740&amp;quot;:276}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;10&quot; data-list-defn-props=&quot;{&amp;quot;335551500&amp;quot;:0,&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;14&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Familiarity with infrastructure as code, for example CDK or Terraform.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:60}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;10&quot; data-list-defn-props=&quot;{&amp;quot;335551500&amp;quot;:0,&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;15&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;Exposure to observability tooling, incident response, or production monitoring practices.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:60}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;ul&gt;
&lt;li data-leveltext=&quot;&quot; data-font=&quot;Symbol&quot; data-listid=&quot;10&quot; data-list-defn-props=&quot;{&amp;quot;335551500&amp;quot;:0,&amp;quot;335552541&amp;quot;:1,&amp;quot;335559685&amp;quot;:720,&amp;quot;335559991&amp;quot;:360,&amp;quot;469769226&amp;quot;:&amp;quot;Symbol&amp;quot;,&amp;quot;469769242&amp;quot;:[8226],&amp;quot;469777803&amp;quot;:&amp;quot;left&amp;quot;,&amp;quot;469777804&amp;quot;:&amp;quot;&amp;quot;,&amp;quot;469777815&amp;quot;:&amp;quot;hybridMultilevel&amp;quot;}&quot; data-aria-posinset=&quot;16&quot; data-aria-level=&quot;1&quot;&gt;&lt;span data-contrast=&quot;none&quot;&gt;A broader understanding of LLM concepts such as tokens, embeddings, hallucinations, and safe use cases in software delivery.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:60}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;span style=&quot;color: rgb(255, 255, 255);&quot; data-ccp-props=&quot;{&amp;quot;335559739&amp;quot;:60}&quot;&gt;#LI-Hybrid&lt;/span&gt;&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;strong&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;About Us&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-olk-copy-source=&quot;MessageBody&quot;&gt;Diligent is the AI leader in governance, risk and compliance (GRC) SaaS solutions, helping more than 1 million users and 700,000 board members to clarify risk and elevate governance. The Diligent One Platform gives practitioners, the C-Suite and the board a consolidated view of their entire GRC practice so they can more effectively manage risk, build greater resilience and make better decisions, faster.&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;div&gt;&lt;span data-teams=&quot;true&quot;&gt;At Diligent, we&#39;re building the future with people who think boldly and move fast. &amp;nbsp;Whether you&#39;re designing systems that leverage large language models or part of a team reimaging workflows with AI, you&#39;ll help us unlock entirely new ways of working and thinking. &amp;nbsp;Curiosity is in our DNA, we look for individuals willing to ask the big questions and experiment fearlessly - those who embrace change not as a challenge, but as an opportunity. &amp;nbsp;The future belongs to those who keep learning, and we are building it together. &amp;nbsp;At Diligent, you’re not just building the future - you’re an agent of positive change, joining a global community on a mission to make an impact.&lt;/span&gt;&lt;/div&gt;
&lt;p&gt;Learn more at&amp;nbsp;diligent.com or follow us on&amp;nbsp;&lt;u&gt;&lt;a id=&quot;OWA170dad44-6a69-e1e1-d720-601cd59ec77c&quot; class=&quot;x_x_x_OWAAutoLink&quot; href=&quot;https://www.linkedin.com/company/diligent-board-member-services/mycompany/verification/&quot; data-outlook-id=&quot;c606bc91-5052-4d3a-a1d1-ed00ede365d9&quot; data-linkindex=&quot;1&quot; data-auth=&quot;NotApplicable&quot;&gt;LinkedIn&lt;/a&gt;&lt;/u&gt;&amp;nbsp;and&amp;nbsp;&lt;u&gt;&lt;a id=&quot;OWA153deb8c-7641-f6fc-97cb-65df680002a3&quot; class=&quot;x_x_x_OWAAutoLink&quot; href=&quot;https://www.facebook.com/DiligentCorporation/&quot; data-outlook-id=&quot;07f4e461-6294-4482-a624-e58c27cd6199&quot; data-linkindex=&quot;2&quot; data-auth=&quot;NotApplicable&quot;&gt;Facebook&lt;/a&gt;&lt;/u&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;What Diligent Offers You&lt;/strong&gt;&amp;nbsp;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Creativity is ingrained in our culture.&lt;/strong&gt; We are innovative collaborators by nature. We thrive in exploring how things can be differently both in our internal processes and to help our clients&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;We care about our people.&amp;nbsp;&lt;/strong&gt;Diligent offers a flexible work environment, global days of service, comprehensive health benefits, meeting free days, generous time off policy and wellness programs&amp;nbsp;to name a few&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;We have teams all over the world&lt;/strong&gt;. We may be headquartered in New York City, but we have office hubs in Washington D.C., Vancouver, London, Galway, Budapest, Munich, Bengaluru, Singapore, and Sydney.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Diversity is important to us.&lt;/strong&gt; Growing, maintaining and promoting a diverse team is a top priority for us. We foster and encourage diversity through our Employee Resource Groups and provide access to resources and education to support the education of our team, facilitate dialogue, and foster understanding.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;Diligent created the modern governance movement. Our world-changing idea is to empower leaders with the technology, insights and connections they need to drive greater impact and accountability – to lead with purpose. Our employees are passionate, smart, and creative people who not only want to help build the software company of the future, but who want to make the world a more sustainable, equitable and better place.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;Headquartered in New York, Diligent has offices in Washington D.C.,&amp;nbsp; London, Galway, Budapest, Vancouver, Bengaluru, Munich, Singapore and Sydney.  &amp;nbsp;To foster strong collaboration and connection, this role will follow a hybrid work model. If you are within a commuting distance to one of our Diligent office locations, you will be expected to&amp;nbsp;&lt;strong&gt;work onsite at least 50% of the time.&lt;/strong&gt;&amp;nbsp;We believe that in-person engagement helps drive innovation, teamwork, and a strong sense of community.&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;sub&gt;We are a drug free workplace. Diligent is proud to be an equal opportunity employer. We do not discriminate based on race, color, religious creed, sex, national origin, ancestry, citizenship status, pregnancy, childbirth, physical disability, mental disability, age, military status, protected veteran status, marital status, registered domestic partner or civil union status, gender (including sex stereotyping and gender identity or expression), medical condition (including, but not limited to, cancer related or HIV/AIDS related), genetic information, or sexual orientation in accordance with applicable federal, state and local laws.&amp;nbsp;We also consider qualified applicants regardless of criminal histories, consistent with legal requirements. See also&amp;nbsp;Diligent&#39;s &lt;a href=&quot;https://www.diligent.com/company/eeo-policy/&quot;&gt;EEO Policy&lt;/a&gt; and &lt;a href=&quot;https://www.diligent.com/-/media/project/diligent/master/eeo-is-the-law-poster-eeocselfprintposter-and-ofccp-supplement-from-20170719.pdf?rev=96fafda8-f51d-44b6-a380-9af42898f526&amp;amp;hash=614AE342F4AB51A091EA3E15F84F7E49&quot; target=&quot;_blank&quot;&gt;Know Your Rights&lt;/a&gt;.&amp;nbsp;We are committed to providing reasonable accommodations for qualified individuals with disabilities and disabled veterans in our job application procedures. If you need assistance or an accommodation due to a disability, you may contact us at &lt;a href=&quot;mailto:recruitment@diligent.com&quot;&gt;recruitment@diligent.com&lt;/a&gt;.&lt;/sub&gt;&lt;/p&gt;
&lt;p&gt;&lt;sub&gt;&lt;strong&gt;To all recruitment agencies:&lt;/strong&gt; Diligent does not accept unsolicited agency resumes. Please do not forward resumes to our jobs alias, Diligent employees or any other organization location. Diligent is not responsible for any fees related to unsolicited resumes.&lt;/sub&gt;&lt;/p&gt;&lt;/div&gt;

nvp-diligent-corporation:greenhouse:6006.descriptionHtml:
&lt;p&gt;&lt;span data-olk-copy-source=&quot;MessageBody&quot;&gt;Diligent is looking for a Technical Director of Data Engineering to help design and build the next generation of data and AI infrastructure powering our products and internal platforms.&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;This is not a traditional management role. We are looking for an experienced builder; someone who still enjoys writing code, debugging distributed systems, evaluating frameworks, and getting hands-on with architecture and implementation.&lt;/p&gt;
&lt;p&gt;You will work across large-scale ingestion pipelines, search systems, AI/LLM infrastructure, event-driven architectures, vector databases, analytics platforms, and real-time data processing. You should be equally comfortable discussing high-level architecture with senior leadership and diving into a failing Kubernetes pod or optimizing a Spark job.&lt;/p&gt;
&lt;p&gt;The ideal candidate has strong opinions informed by real-world experience, understands tradeoffs deeply, and can move quickly without creating unnecessary complexity.&lt;/p&gt;
&lt;h3&gt;What You’ll Do&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Design and build scalable data platforms and distributed processing systems&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Develop modern ingestion, transformation, and retrieval pipelines for structured and unstructured data&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Build systems supporting AI/LLM applications, semantic search, RAG pipelines, vector search, and agentic workflows&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Work hands-on with engineering teams to implement production-grade solutions rather than producing slideware&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Evaluate and standardize frameworks, tooling, and infrastructure patterns across teams&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Improve performance, reliability, observability, and cost efficiency of data systems&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Partner with product and platform engineering teams to accelerate delivery of AI-native capabilities&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Drive pragmatic engineering decisions balancing speed, maintainability, and operational simplicity&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Mentor engineers technically through design reviews, architecture guidance, and pair debugging&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Help establish engineering standards around CI/CD, testing, data quality, monitoring, and operational excellence&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;What We’re Looking For&lt;/h3&gt;
&lt;h3&gt;Strong Hands-On Engineering Experience&lt;/h3&gt;
&lt;p&gt;Candidates should have significant real-world experience building and operating production systems using many of the following:&lt;/p&gt;
&lt;h4&gt;Data &amp;amp; Distributed Systems&lt;/h4&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Airflow&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Elasticsearch / OpenSearch&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Vector databases and semantic retrieval systems&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;MongoDB, PostgreSQL, DynamoDB, or similar platforms&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;h4&gt;Cloud &amp;amp; Infrastructure&lt;/h4&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;AWS&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;AWS CDK&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Serverless architectures&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Distributed observability and monitoring stacks&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;h4&gt;AI / Search / Modern Data Applications&lt;/h4&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;LLM integration patterns&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;RAG architectures&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Embeddings and vector search&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;MCP servers and AI orchestration frameworks&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;LangChain, LlamaIndex, DSPy, or similar ecosystems&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;AI evaluation, tracing, and observability tooling&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Search relevance and ranking systems&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;h4&gt;Backend Engineering&lt;/h4&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Python strongly preferred&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Experience with Java, Go, or TypeScript is a plus&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;API design and distributed service architectures&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Event-driven and asynchronous systems&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;The Right Candidate&lt;/h2&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Still enjoys building and debugging systems directly&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Has strong technical depth, not just architectural vocabulary&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Comfortable operating in ambiguity and fast-moving environments&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Understands how to simplify systems instead of endlessly abstracting them&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Has experience modernizing legacy platforms and evolving architectures incrementally&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Can distinguish between engineering fundamentals and hype cycles&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Values shipping working systems over theoretical perfection&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;What Success Looks Like&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Engineering teams can move faster because the underlying platforms are reliable and scalable&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;AI and data systems become production-grade rather than experimental prototypes&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Infrastructure costs and operational complexity are reduced through better architecture&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Search, ingestion, and retrieval systems improve significantly in performance and relevance&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Teams adopt consistent, maintainable technical patterns without excessive bureaucracy&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;Nice to Have&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Experience with large-scale news, document, or regulatory data pipelines&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Experience with search relevancy tuning and semantic retrieval&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Exposure to governance, compliance, risk, or enterprise SaaS platforms&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Familiarity with modern AI engineering workflows and agentic systems&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Experience supporting both startup-speed execution and enterprise-scale operations&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;div&gt;&amp;nbsp;&lt;/div&gt;&lt;div class=&quot;content-pay-transparency&quot;&gt;&lt;div class=&quot;pay-input&quot;&gt;&lt;div class=&quot;title&quot;&gt;Pay Range&lt;/div&gt;&lt;div class=&quot;pay-range&quot;&gt;&lt;span&gt;$180,000&lt;/span&gt;&lt;span class=&quot;divider&quot;&gt;&amp;mdash;&lt;/span&gt;&lt;span&gt;$210,000 CAD&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;strong&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;About Us&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-olk-copy-source=&quot;MessageBody&quot;&gt;Diligent is the AI leader in governance, risk and compliance (GRC) SaaS solutions, helping more than 1 million users and 700,000 board members to clarify risk and elevate governance. The Diligent One Platform gives practitioners, the C-Suite and the board a consolidated view of their entire GRC practice so they can more effectively manage risk, build greater resilience and make better decisions, faster.&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;div&gt;&lt;span data-teams=&quot;true&quot;&gt;At Diligent, we&#39;re building the future with people who think boldly and move fast. &amp;nbsp;Whether you&#39;re designing systems that leverage large language models or part of a team reimaging workflows with AI, you&#39;ll help us unlock entirely new ways of working and thinking. &amp;nbsp;Curiosity is in our DNA, we look for individuals willing to ask the big questions and experiment fearlessly - those who embrace change not as a challenge, but as an opportunity. &amp;nbsp;The future belongs to those who keep learning, and we are building it together. &amp;nbsp;At Diligent, you’re not just building the future - you’re an agent of positive change, joining a global community on a mission to make an impact.&lt;/span&gt;&lt;/div&gt;
&lt;p&gt;Learn more at&amp;nbsp;diligent.com or follow us on&amp;nbsp;&lt;u&gt;&lt;a id=&quot;OWA170dad44-6a69-e1e1-d720-601cd59ec77c&quot; class=&quot;x_x_x_OWAAutoLink&quot; href=&quot;https://www.linkedin.com/company/diligent-board-member-services/mycompany/verification/&quot; data-outlook-id=&quot;c606bc91-5052-4d3a-a1d1-ed00ede365d9&quot; data-linkindex=&quot;1&quot; data-auth=&quot;NotApplicable&quot;&gt;LinkedIn&lt;/a&gt;&lt;/u&gt;&amp;nbsp;and&amp;nbsp;&lt;u&gt;&lt;a id=&quot;OWA153deb8c-7641-f6fc-97cb-65df680002a3&quot; class=&quot;x_x_x_OWAAutoLink&quot; href=&quot;https://www.facebook.com/DiligentCorporation/&quot; data-outlook-id=&quot;07f4e461-6294-4482-a624-e58c27cd6199&quot; data-linkindex=&quot;2&quot; data-auth=&quot;NotApplicable&quot;&gt;Facebook&lt;/a&gt;&lt;/u&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;What Diligent Offers You&lt;/strong&gt;&amp;nbsp;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;Creativity is ingrained in our culture.&lt;/strong&gt; We are innovative collaborators by nature. We thrive in exploring how things can be differently both in our internal processes and to help our clients&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;We care about our people.&amp;nbsp;&lt;/strong&gt;Diligent offers a flexible work environment, global days of service, comprehensive health benefits, meeting free days, generous time off policy and wellness programs&amp;nbsp;to name a few&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;We have teams all over the world&lt;/strong&gt;. We may be headquartered in New York City, but we have office hubs in Washington D.C., Vancouver, London, Galway, Budapest, Munich, Bengaluru, Singapore, and Sydney.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Diversity is important to us.&lt;/strong&gt; Growing, maintaining and promoting a diverse team is a top priority for us. We foster and encourage diversity through our Employee Resource Groups and provide access to resources and education to support the education of our team, facilitate dialogue, and foster understanding.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;Diligent created the modern governance movement. Our world-changing idea is to empower leaders with the technology, insights and connections they need to drive greater impact and accountability – to lead with purpose. Our employees are passionate, smart, and creative people who not only want to help build the software company of the future, but who want to make the world a more sustainable, equitable and better place.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;Headquartered in New York, Diligent has offices in Washington D.C.,&amp;nbsp; London, Galway, Budapest, Vancouver, Bengaluru, Munich, Singapore and Sydney.  &amp;nbsp;To foster strong collaboration and connection, this role will follow a hybrid work model. If you are within a commuting distance to one of our Diligent office locations, you will be expected to&amp;nbsp;&lt;strong&gt;work onsite at least 50% of the time.&lt;/strong&gt;&amp;nbsp;We believe that in-person engagement helps drive innovation, teamwork, and a strong sense of community.&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;sub&gt;We are a drug free workplace. Diligent is proud to be an equal opportunity employer. We do not discriminate based on race, color, religious creed, sex, national origin, ancestry, citizenship status, pregnancy, childbirth, physical disability, mental disability, age, military status, protected veteran status, marital status, registered domestic partner or civil union status, gender (including sex stereotyping and gender identity or expression), medical condition (including, but not limited to, cancer related or HIV/AIDS related), genetic information, or sexual orientation in accordance with applicable federal, state and local laws.&amp;nbsp;We also consider qualified applicants regardless of criminal histories, consistent with legal requirements. See also&amp;nbsp;Diligent&#39;s &lt;a href=&quot;https://www.diligent.com/company/eeo-policy/&quot;&gt;EEO Policy&lt;/a&gt; and &lt;a href=&quot;https://www.diligent.com/-/media/project/diligent/master/eeo-is-the-law-poster-eeocselfprintposter-and-ofccp-supplement-from-20170719.pdf?rev=96fafda8-f51d-44b6-a380-9af42898f526&amp;amp;hash=614AE342F4AB51A091EA3E15F84F7E49&quot; target=&quot;_blank&quot;&gt;Know Your Rights&lt;/a&gt;.&amp;nbsp;We are committed to providing reasonable accommodations for qualified individuals with disabilities and disabled veterans in our job application procedures. If you need assistance or an accommodation due to a disability, you may contact us at &lt;a href=&quot;mailto:recruitment@diligent.com&quot;&gt;recruitment@diligent.com&lt;/a&gt;.&lt;/sub&gt;&lt;/p&gt;
&lt;p&gt;&lt;sub&gt;&lt;strong&gt;To all recruitment agencies:&lt;/strong&gt; Diligent does not accept unsolicited agency resumes. Please do not forward resumes to our jobs alias, Diligent employees or any other organization location. Diligent is not responsible for any fees related to unsolicited resumes.&lt;/sub&gt;&lt;/p&gt;&lt;/div&gt;

nvp-kyo:greenhouse:7585909.descriptionHtml:
&lt;div class=&quot;ipl-richtexteditor-block&quot; style=&quot;text-align: center;&quot; data-block=&quot;true&quot; data-editor=&quot;dunn6&quot; data-offset-key=&quot;1sedq-0-0&quot;&gt;
&lt;div class=&quot;public-DraftStyleDefault-block public-DraftStyleDefault-ltr&quot; data-offset-key=&quot;1sedq-0-0&quot;&gt;
&lt;p style=&quot;text-align: center;&quot;&gt;Kyo is a leading provider of Applied Behavior Analysis (ABA), an evidence-based therapy for individuals with autism. Kyo serves thousands of children and teens across 11 states. Every day, we seek to achieve the unachievable for our clients.&lt;/p&gt;
&lt;p style=&quot;text-align: center;&quot;&gt;&lt;strong&gt;A $2000 sign-on bonus and relocation assistance are available!&lt;/strong&gt;&lt;/p&gt;
&lt;p style=&quot;text-align: center;&quot;&gt;&lt;strong&gt;&lt;em&gt;Pay Rate for direct therapy: $25.00 per hour&lt;br&gt;&lt;/em&gt;&lt;/strong&gt;&lt;strong&gt;&lt;em&gt;Pay Rate for supervision duties: $30.00 per hour&lt;/em&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;p style=&quot;text-align: center;&quot;&gt;&lt;strong&gt;&lt;em&gt;Kyo is seeking Full-Time candidates with open availability Monday through Friday from 8am-7pm.&lt;br&gt;Program Supervisors will be provided 50% of hours as supervision duties.&amp;nbsp;&lt;/em&gt;&lt;/strong&gt;&lt;/p&gt;
&lt;h1 style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;Program Supervisors at Kyo:&lt;/strong&gt;&lt;/span&gt;&lt;/h1&gt;
&lt;ul style=&quot;text-align: left;&quot;&gt;
&lt;li&gt;Deliver play-based, evidence-based ABA therapy to support children with autism in achieving meaningful goals across home, school, and community settings.&lt;/li&gt;
&lt;li&gt;Train, mentor, and coach Behavior Therapists and caregivers through observation, feedback, and modeling to maintain treatment integrity and support skill development.&lt;/li&gt;
&lt;li&gt;Collaborate with a BCBA on assessments, treatment planning, goal development, and the creation or updating of program materials and client documentation.&lt;br&gt;&lt;br&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h1 style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;WHY CHOOSE US?&lt;/strong&gt;&lt;/span&gt;&lt;/h1&gt;
&lt;ul style=&quot;text-align: left;&quot;&gt;
&lt;li&gt;&lt;strong&gt;Paid ABA Training and Growth: &lt;/strong&gt;After completing our Behavior Therapist Academy,&lt;strong&gt; &lt;/strong&gt;paid accrual for BCBA hours will be provided.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Comprehensive Benefits:&lt;/strong&gt; Medical, vision, dental and life insurance benefits for staff working 30+ hours/week; mileage reimbursement, referral bonuses, 401k and EAP.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;A Gateway to Much More:&lt;/strong&gt; Acquire skills that open doors across healthcare and beyond. Kyo will help pay for your tuition on BCBA coursework.&lt;br&gt;&lt;br&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h1 style=&quot;text-align: left;&quot;&gt;&lt;span style=&quot;font-size: 12pt;&quot;&gt;&lt;strong&gt;JOB REQUIREMENTS&lt;/strong&gt;&lt;/span&gt;&lt;/h1&gt;
&lt;ul style=&quot;text-align: left;&quot;&gt;
&lt;li style=&quot;text-align: left;&quot;&gt;&lt;strong&gt;Education: &lt;/strong&gt;Bachelor’s degree (BA/BS required). Willingness to obtain/maintain RBT certification or applicable state ABA license. Enrollment in a BACB-verified course sequence &lt;em&gt;and&lt;/em&gt;&lt;/li&gt;
&lt;ul&gt;
&lt;li&gt;12+ semester units in ABA with one year of ABA experience &lt;strong&gt;OR&lt;/strong&gt;&lt;/li&gt;
&lt;li&gt;Two years of experience designing/implementing behavior intervention services.&lt;/li&gt;
&lt;/ul&gt;
&lt;/ul&gt;
&lt;ul style=&quot;text-align: left;&quot;&gt;
&lt;li&gt;&lt;strong&gt;Experience:&lt;/strong&gt; Minimum 2 years working with children with developmental disabilities using ABA principles.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Availability: &lt;/strong&gt;Weekday afternoon availability required (3-7pm).&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Transportation:&lt;/strong&gt; Reliable vehicle with valid in-state driver’s license and insurance. Willingness to travel approximately 45 minutes between work locations, with paid drive time.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Technology Skills:&lt;/strong&gt; Basic computer skills, including experience using a tablet and ability to navigate various online platforms. Access to a smartphone is a requirement of this position.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Background Check:&lt;/strong&gt; Ability to pass DOJ/FBI background check including fingerprinting and TB test (if applicable).&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Physical Ability:&lt;/strong&gt; The job involves extensive standing, walking, reaching, bending, kneeling, and crouching. Must be able to lift a minimum of 50 pounds. Ability to communicate clearly and participate in physical and play-based therapies.&lt;br&gt;&lt;br&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p style=&quot;text-align: left;&quot;&gt;&lt;strong&gt;What locations do San Diego Program Supervisors work in?&amp;nbsp;&lt;/strong&gt;&lt;span data-sheets-root=&quot;1&quot;&gt;Bonita, Cardiff by the Sea, Carlsbad, Chula Vista, Coronado, Crest, El Cajon, Escondido, Fallbrook, Imperial Beach, Lakeside, La Jolla, La Mesa, Leon Grove, Lincoln Acres, Mount Laguna, Oceanside, Poway, Ramona, Rancho Santa Fe, San Diego, San Marcos, Santa Ysabel, Solana Beach, Spring Beach, Vista&lt;/span&gt;, and anywhere in between! *Program Supervisors may commute approximately 45 minutes from their preferred location.&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p style=&quot;text-align: center;&quot;&gt;&lt;strong&gt;Apply today to meet with our Talent team and learn more!&lt;/strong&gt;&lt;/p&gt;
&lt;/div&gt;
&lt;/div&gt;

paradigmxyz-mesh-connect:greenhouse:5159.descriptionHtml:
&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;&lt;strong&gt;About Mesh&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;At Mesh, our mission is to enable consumers to pay and be paid with any asset. Today, trillions of dollars in tokenized assets exist but remain largely unusable for everyday commerce. Mesh is bridging this gap by making crypto payments reliable, useful, and ubiquitous. We combine a powerful orchestration engine with a seamless consumer app to unlock liquidity for the world. Backed by leading investors like PayPal Ventures, Paradigm, and Galaxy Ventures, we are building the infrastructure for the next era of the global economy. Join us!&lt;/p&gt;&lt;/div&gt;&lt;p&gt;&lt;strong&gt;Overview&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Mesh is looking for a Project Manager to be the operational backbone of our most complex, high-stakes customer integrations.&lt;/p&gt;
&lt;p&gt;For our most strategic customers, we deploy a three-person leadership pod: a Strategic Account Manager who navigates the client&#39;s business, a Product Manager who architects the technical solution, and you — the person who makes sure all of it actually ships.&lt;/p&gt;
&lt;p&gt;This is not a note-taking role. At its core, your mandate is to maintain an airtight, living record of every commitment we&#39;ve made to our largest customers — and to know, at any moment, exactly where each one stands. You&#39;ll own the operational heartbeat of each integration: transforming tangled cross-functional dependencies into a clear, executable path to launch, and driving relentless accountability for who does what next.&lt;/p&gt;
&lt;p&gt;Because we&#39;re a fast-moving startup, we hold everyone on the team to an entrepreneurial standard. We&#39;re looking for someone who doesn&#39;t just manage work — they actively automate it. You should be building systems, templates, and tooling that give you 10x leverage, so you can operate at the scale of a team of one without anything slipping through the cracks.&lt;/p&gt;
&lt;p&gt;If you&#39;re the kind of person who stays three steps ahead, thrives in ambiguity, and instinctively reaches for a script or a workflow when something feels manual — this role was built for you.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;What You&#39;ll Do&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Drive the Log: You are the ultimate owner of the deployment timeline. You maintain absolute clarity on every internal and external dependency, holding both Mesh and the client’s teams accountable to the schedule.&lt;/li&gt;
&lt;li&gt;Enable Engineering Velocity: You act as the translation layer between project milestones and engineering execution. You take the solutions designed by our Product team and turn them into precise, highly organized tickets, ensuring our developers have exactly what they need to build without distraction.&lt;/li&gt;
&lt;li&gt;Coordinate the Pod: You work in lockstep with the Strategic Account Manager and Product Manager. While they figure out &lt;em&gt;what&lt;/em&gt; to build and &lt;em&gt;who&lt;/em&gt; to influence, you ensure the actual work gets sequenced, assigned, and delivered on time.&lt;/li&gt;
&lt;li&gt;High Leverage &amp;amp; Automation: You ruthlessly optimize and automate your own operational workflows. You utilize modern tools (AI, Zapier, scripts, advanced Jira automations) to scale your output, minimizing manual administrative work so you can focus on proactively unblocking the team.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Who You Are&amp;nbsp;&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;3+ years of project management experience in a fast-paced B2B SaaS, fintech, or technical software startup, including experience working with enterprise clients&lt;/li&gt;
&lt;li&gt;Entrepreneurial Drive: You are a self-starter with a demonstrated history of taking initiative. You thrive in ambiguity and take absolute ownership of your outcomes.&lt;/li&gt;
&lt;li&gt;Relentless Organization: You are a force of operational nature. You obsess over the details, sweat the edge cases, and ensure absolutely nothing slips through the cracks.&lt;/li&gt;
&lt;li&gt;Execution Focus: You take pride in driving a project to completion. You are comfortable running stand-ups, managing Jira boards, and holding cross-functional peers accountable to their deadlines.&lt;/li&gt;
&lt;li&gt;Technical Literacy: While you do not need to write code or architect systems, you are highly comfortable working in a technical, API-first environment and can translate project phases into actionable engineering tasks.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;The annual base salary range for this role is $141,000 - $175,000 in San Francisco and New York. The compensation range provided may span multiple career levels and will be narrowed during the interview process based on factors including a candidate’s experience, skills, qualifications, and geographic location. For candidates outside of San Francisco and New York, compensation will be adjusted to reflect the applicable market and location-based pay band. The base salary range listed excludes commission (if applicable), equity, and benefits. The pay range represents the minimum and maximum target for new-hire compensation. Actual compensation may vary and may be higher or lower depending on individual circumstances.&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;p&gt;&lt;strong&gt;Why You’ll Love It Here&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;At Mesh, you&#39;re not stepping into a typical role—you&#39;re joining a rocket ship in mid-liftoff. You&#39;ll tackle complex, meaningful problems that actually move an industry forward, working alongside a sharp, motivated team that moves quickly, collaborates deeply, and expects everyone to operate with ownership. This is the kind of place where you&#39;ll see your work ship fast, make real impact, and be able to point to something and say, &quot;I built that.&quot; You&#39;ll grow fast, level up your skills, and get a front-row seat to how a high-growth company scales from the inside, with competitive comp, solid benefits, and room to stretch your craft all coming standard. If you&#39;re energized by building, learning, and shaping something big—this is where you&#39;ll want to be.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;In-Office Expectations&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Employees based in our &lt;strong&gt;San Francisco, New York, and Bangalore&lt;/strong&gt; hubs are expected to work from the office at least 40% of the time (approximately two days per week). This expectation may vary slightly depending on role, team, and business needs. Certain roles that require closer cross-functional collaboration or operational support may have additional in-office requirements, which will be discussed during the interview process. Our hybrid approach is designed to balance meaningful in-person collaboration, team building, and real-time decision-making with the flexibility to work remotely. We believe this structure supports strong execution while preserving autonomy and focus time.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;How We Care For Our Team&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;We believe great work happens when people feel valued and supported. That starts with competitive salary and equity that grows as you and the company grow, plus comprehensive health coverage for you and your family. We offer unlimited PTO—and we mean it. Take the time you need to recharge and show up at your best.&lt;/p&gt;
&lt;p&gt;We&#39;re invested in your growth with a dedicated budget for courses, conferences, and certifications. Work from wherever you&#39;re most productive with our remote-friendly approach, and count on having the top-tier tools and equipment you need to do exceptional work.&lt;/p&gt;
&lt;p&gt;Mesh Pay is committed to equal employment opportunities regardless of race, color, genetic information, creed, religion, sex, sexual orientation, gender identity, lawful alien status, national origin, age, marital status, and non-job related physical or mental disability, or protected veteran status. Pursuant to the San Francisco Fair Chance Ordinance, we will consider for employment qualified applicants with arrest and conviction records.&lt;/p&gt;&lt;/div&gt;

playground-psiquantum:greenhouse:7565244.descriptionHtml:
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;PsiQuantum’s&amp;nbsp;mission is to build the first useful quantum computers—machines capable of delivering the breakthroughs the field has long promised. Since our founding in 2016, our singular focus has been to build and deploy million-qubit, fault-tolerant quantum systems.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Quantum computers harness the laws of quantum mechanics to solve problems that even the most advanced supercomputers or AI systems will never reach. Their impact will span energy, pharmaceuticals, finance, agriculture, transportation, materials, and other foundational industries.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Our architecture and approach&amp;nbsp;is&amp;nbsp;based on silicon photonics. By&amp;nbsp;leveraging&amp;nbsp;the advanced semiconductor manufacturing industry—including partners like GlobalFoundries—we use the same high-volume processes that already produce billions of chips for telecom and consumer electronics. Photonics offers natural advantages for scale: photons&amp;nbsp;don’t&amp;nbsp;feel heat, are immune to electromagnetic interference, and integrate with existing cryogenic cooling and standard fiber-optic infrastructure.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;In 2024,&amp;nbsp;PsiQuantum&amp;nbsp;announced government-funded projects to support the build-out of our first utility-scale quantum computers in Brisbane, Australia, and Chicago, Illinois. These initiatives reflect a growing recognition that quantum computing will be strategically and economically defining—and that now is the time to scale.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;PsiQuantum&amp;nbsp;also develops the algorithms and software needed to make these systems commercially valuable. Our application, software, and industry teams work directly with leading Fortune 500 companies—including Lockheed Martin, Mercedes-Benz, Boehringer Ingelheim, and Mitsubishi Chemical—to prepare quantum solutions for real-world impact.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Quantum computing is not an extension of classical computing. It&amp;nbsp;represents&amp;nbsp;a fundamental shift—and a path to mastering challenges that cannot be&amp;nbsp;solved&amp;nbsp;any other way. The potential is enormous, and we have a clear&amp;nbsp;path&amp;nbsp;to make it real.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Come join us.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Job Summary:&lt;/strong&gt;&lt;/p&gt;
&lt;p data-renderer-start-pos=&quot;1&quot;&gt;Quantum computing promises to solve many important problems that could never be solved on any conventional computer. At PsiQuantum, we’re building a general-purpose silicon photonic quantum computer to tackle these very problems.&amp;nbsp;&lt;/p&gt;
&lt;p data-renderer-start-pos=&quot;233&quot;&gt;We are looking for an energetic, highly motivated Photonic Integrated Circuit (PIC) engineer who will be responsible for the design, layout, and verification of photonic integrated circuits for a linear optic quantum computer (LOQC).&lt;/p&gt;
&lt;p data-renderer-start-pos=&quot;468&quot;&gt;We’re looking for a creative and innovative individual with strong fundamentals in the design, optimization, layout, and fabrication of integrated optical devices. This role is focused on pushing the boundaries of high-performance integrated photonic components and circuits. The role requires excellent python skills, experience with python-based layout tools and foundry tape outs, and experience with collaborative coding environments such as git.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Responsibilities:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Interacts with device, hardware, and system design teams to assist in overall development of Photonics and Quantum Optics photonic systems and devices.&lt;/li&gt;
&lt;li&gt;Supports foundry tape outs with photonic device design, design of experiments, layout, design verification, PDK development, and software development.&lt;/li&gt;
&lt;li&gt;Develops comprehensive documentation for tapeouts.&lt;/li&gt;
&lt;li&gt;Provides multi-disciplinary support to component and systems teams by resolving technical issues associated with components, parts, or systems.&lt;/li&gt;
&lt;li&gt;Applies quantitative analysis in determining root cause of highly technical problems and proposes, develops, and implements solutions for corrective action.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Experience/Qualifications:&lt;/strong&gt;&lt;/p&gt;
&lt;p data-renderer-start-pos=&quot;1&quot;&gt;&lt;strong data-renderer-mark=&quot;true&quot;&gt;Education&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-renderer-start-pos=&quot;1&quot;&gt;PhD or equivalent in Electrical Engineering, Physics, Materials Science.&lt;/li&gt;
&lt;/ul&gt;
&lt;p data-renderer-start-pos=&quot;90&quot;&gt;&lt;strong data-renderer-mark=&quot;true&quot;&gt;Experience&lt;/strong&gt;&lt;/p&gt;
&lt;ul class=&quot;ak-ul&quot; data-indent-level=&quot;1&quot;&gt;
&lt;li&gt;
&lt;p data-renderer-start-pos=&quot;104&quot;&gt;5+ years of relevant work or academic research experience in integrated photonics.&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p data-renderer-start-pos=&quot;190&quot;&gt;&lt;strong data-renderer-mark=&quot;true&quot;&gt;Knowledge, Skills, and Abilities&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-renderer-start-pos=&quot;190&quot;&gt;Strong fundamentals of the design and characterization of photonic devices and circuits.&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;190&quot;&gt;Proven proficiency in Python programming for numerical analysis, data manipulation, automation and photonic circuit layout.&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;190&quot;&gt;Experience with silicon photonic manufacturing processes and foundry tapeouts.&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;190&quot;&gt;Strong fundamentals in electro-magnetic theory, statistical analysis, and quantum mechanics.&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;190&quot;&gt;Extensive experience with simulation platforms, particularly Lumerical, for designing and simulating photonic devices and circuits.&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;190&quot;&gt;Proven team player with an ability to work effectively across departments, sites, time zones.&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;190&quot;&gt;Excellent verbal and written communication skills.&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;190&quot;&gt;Strong analytical and detail oriented problem-solving skills.&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;190&quot;&gt;Proven experience executing cross-department complex projects.&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;190&quot;&gt;Ability to work independently with limited direction.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;PsiQuantum provides equal employment opportunity for all applicants and employees. PsiQuantum does not unlawfully discriminate on the basis of race, color, religion, sex (including pregnancy, childbirth, or related medical conditions), gender identity, gender expression, national origin, ancestry, citizenship, age, physical or mental disability, military or veteran status, marital status, domestic partner status, sexual orientation, genetic information, or any other basis protected by applicable laws.&lt;/p&gt;
&lt;p&gt;&lt;strong data-stringify-type=&quot;bold&quot;&gt;Note: PsiQuantum will only reach out to you using an official PsiQuantum email address and will never ask you for bank account information as part of the interview process. Please report any suspicious activity to &lt;/strong&gt;&lt;strong data-stringify-type=&quot;bold&quot;&gt;&lt;a class=&quot;c-link&quot; href=&quot;mailto:recruiting@psiquantum.com&quot; target=&quot;_blank&quot; data-stringify-link=&quot;mailto:recruiting@psiquantum.com&quot; data-sk=&quot;tooltip_parent&quot;&gt;recruiting@psiquantum.com&lt;/a&gt;&lt;/strong&gt;&lt;strong data-stringify-type=&quot;bold&quot;&gt;.&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;We are not accepting unsolicited resumes from employment agencies.&lt;/p&gt;&lt;div class=&quot;content-pay-transparency&quot;&gt;&lt;div class=&quot;pay-input&quot;&gt;&lt;div class=&quot;description&quot;&gt;&lt;p&gt;The ranges below reflect the target ranges for a new hire base salary. One is for the Bay Area (within 50 miles of HQ, Palo Alto), the second one (if applicable) is for elsewhere in the US (beyond 50 miles of HQ, Palo Alto). If there is only one range, it is for the specific location of where the position will be located.&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;Actual compensation may vary outside of these ranges and is dependent on various factors including but not limited to a candidate&#39;s qualifications including relevant education and training, competencies, experience, geographic location, and business needs. Base pay is only one part of the total compensation package. Full time roles are eligible for equity and benefits. Base pay is subject to change and may be modified in the future.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;title&quot;&gt;U.S. Base Pay Range &lt;/div&gt;&lt;div class=&quot;pay-range&quot;&gt;&lt;span&gt;$160,000&lt;/span&gt;&lt;span class=&quot;divider&quot;&gt;&amp;mdash;&lt;/span&gt;&lt;span&gt;$180,000 USD&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;pay-input&quot;&gt;&lt;div class=&quot;title&quot;&gt;Bay Area Pay Range &lt;/div&gt;&lt;div class=&quot;pay-range&quot;&gt;&lt;span&gt;$183,000&lt;/span&gt;&lt;span class=&quot;divider&quot;&gt;&amp;mdash;&lt;/span&gt;&lt;span&gt;$200,000 USD&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;

playground-psiquantum:greenhouse:7763046.descriptionHtml:
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;PsiQuantum’s&amp;nbsp;mission is to build the first useful quantum computers—machines capable of delivering the breakthroughs the field has long promised. Since our founding in 2016, our singular focus has been to build and deploy million-qubit, fault-tolerant quantum systems.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Quantum computers harness the laws of quantum mechanics to solve problems that even the most advanced supercomputers or AI systems will never reach. Their impact will span energy, pharmaceuticals, finance, agriculture, transportation, materials, and other foundational industries.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Our architecture and approach&amp;nbsp;is&amp;nbsp;based on silicon photonics. By&amp;nbsp;leveraging&amp;nbsp;the advanced semiconductor manufacturing industry—including partners like GlobalFoundries—we use the same high-volume processes that already produce billions of chips for telecom and consumer electronics. Photonics offers natural advantages for scale: photons&amp;nbsp;don’t&amp;nbsp;feel heat, are immune to electromagnetic interference, and integrate with existing cryogenic cooling and standard fiber-optic infrastructure.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;In 2024,&amp;nbsp;PsiQuantum&amp;nbsp;announced government-funded projects to support the build-out of our first utility-scale quantum computers in Brisbane, Australia, and Chicago, Illinois. These initiatives reflect a growing recognition that quantum computing will be strategically and economically defining—and that now is the time to scale.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;PsiQuantum&amp;nbsp;also develops the algorithms and software needed to make these systems commercially valuable. Our application, software, and industry teams work directly with leading Fortune 500 companies—including Lockheed Martin, Mercedes-Benz, Boehringer Ingelheim, and Mitsubishi Chemical—to prepare quantum solutions for real-world impact.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Quantum computing is not an extension of classical computing. It&amp;nbsp;represents&amp;nbsp;a fundamental shift—and a path to mastering challenges that cannot be&amp;nbsp;solved&amp;nbsp;any other way. The potential is enormous, and we have a clear&amp;nbsp;path&amp;nbsp;to make it real.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Come join us.&lt;/span&gt;&lt;span data-ccp-props=&quot;{}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Job Summary:&lt;/strong&gt;&lt;/p&gt;
&lt;p data-renderer-start-pos=&quot;22&quot;&gt;&lt;strong data-renderer-mark=&quot;true&quot;&gt;PsiQuantum is seeking a high-speed photonics experimentalist to develop phase modulators, switches, and other active photonic components for the world’s first fault-tolerant quantum computer.&lt;/strong&gt;&amp;nbsp;&lt;/p&gt;
&lt;p data-renderer-start-pos=&quot;216&quot;&gt;In this role, you will own the &lt;strong data-renderer-mark=&quot;true&quot;&gt;characterization, analysis, and performance validation of high-speed active photonic devices,&amp;nbsp;circuits, and subsystems&lt;/strong&gt;. You will work closely with teams across electronics, manufacturing, test, packaging, and system validation to translate device-level results into robust system-level performance.&amp;nbsp;&lt;/p&gt;
&lt;p data-renderer-start-pos=&quot;548&quot;&gt;The ideal candidate will have deep hands-on experience with high-speed electro-optic characterization and a strong understanding of passive and active photonic components, including electro-optic phase shifters, switches, modulators, and related integrated photonic devices.&amp;nbsp;&lt;/p&gt;
&lt;p data-renderer-start-pos=&quot;825&quot;&gt;&lt;strong data-renderer-mark=&quot;true&quot;&gt;The hiring level and scope for this role will be calibrated to the selected candidate’s experience and strengths. Candidates with relevant PhD/postdoctoral exposure, as well as those with additional industry experience, are encouraged to apply.&lt;/strong&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Responsibilities:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-renderer-start-pos=&quot;3&quot;&gt;Own &lt;strong data-renderer-mark=&quot;true&quot;&gt;high-speed electro-optic characterization and validation of active photonic devices, circuits, and subsystems&lt;/strong&gt;, including electro-optic phase shifters, switches, modulators, and related components.
&lt;ul&gt;
&lt;li data-renderer-start-pos=&quot;3&quot;&gt;Tests include S-parameter measurements, high-speed time domain waveform measurements, switching response, bandwidth, insertion loss, extinction ratio, and related device- and circuit-level metrics.&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;3&quot;&gt;The candidate will need to work across different test configurations, including wafer-level probing, connectorized photonic/electronic devices, packaged assemblies, and integrated builds incorporating photonic chips, PCBs, drivers, FPGAs, firmware, and related hardware.&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;686&quot;&gt;Translate device requirements, system needs, and expected learning objectives into executable characterization plans.&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;686&quot;&gt;&lt;strong data-renderer-mark=&quot;true&quot;&gt;Analyze and model measurement data&lt;/strong&gt; to understand device, circuit and subsystem behavior, diagnose performance limitations, and recommend improvements.&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;686&quot;&gt;Develop new characterization methods, automation tools, and analysis workflows as needed.&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;686&quot;&gt;Collaborate closely with multidisciplinary teams across photonics, electronics, packaging, manufacturing, test, firmware, and system validation to help design, build, test, and improve high-performance photonic chips and assemblies.&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;686&quot;&gt;Document measurement methods, calibration procedures, results, and conclusions clearly and rigorously.&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;686&quot;&gt;Mentor junior team members.&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Experience/Qualifications:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li data-renderer-start-pos=&quot;3&quot;&gt;MS or PhD in electrical engineering, applied physics, optical engineering, photonics, or a related technical discipline. Industry experience is a plus.&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;3&quot;&gt;Deep understanding of integrated photonic devices and circuits, including passive and active components such as waveguides, electro-optic phase shifters, switches, modulators, and related high-speed photonic devices.&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;3&quot;&gt;Hands-on experience with standard RF, microwave, and optical test equipment, including oscilloscopes, signal generators, VNAs, high-speed probes, optical power meters, lasers, photodetectors, and related laboratory equipment.&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;3&quot;&gt;Experience with high-speed electro-optic measurements, including electro-optic S-parameters, high-speed waveform measurements, bandwidth, and related device- and circuit-level metrics.&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;3&quot;&gt;Strong understanding of RF measurement concepts, including S-parameters, impedance matching, bandwidth, signal integrity, calibration, de-embedding, and measurement uncertainty.&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;3&quot;&gt;Experience developing automated test systems, measurement scripts, data pipelines, or analysis tools for photonic, RF, or high-speed electro-optic characterization.&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;3&quot;&gt;Strong data analysis skills, including data visualization, statistical interpretation of measurement results, and data-driven decision-making.&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;3&quot;&gt;Ability to translate device requirements and experimental learning goals into clear test plans, execute measurements, analyze results, and communicate conclusions.&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;3&quot;&gt;Experience with one or more active photonic material platforms, such as thin-film lithium niobate, BTO, doped silicon, InP, GaAs, AlGaAs, InGaAsP, or related electro-optic platforms, is a plus.&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;3&quot;&gt;Understanding of photonic-electronic interfaces and integrated build architectures, including PCBs, RF interconnects, high-speed drivers, FPGAs, TIAs, firmware-controlled test systems, wirebonds, and related electronics, is a plus.&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;3&quot;&gt;Experience with photonic packaging and assembly-level integration is a plus.&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;3&quot;&gt;Experience designing, simulating, or modeling photonic and electro-optic components using tools such as Ansys Lumerical, Tidy3D, COMSOL Multiphysics, Meep, or similar platforms is a plus; experience with RF or high-speed electronic simulation tools such as HFSS, ADS, Cadence AWR, or SPICE-based tools is also a plus.&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;3&quot;&gt;Familiarity with high-volume or manufacturing-oriented test environments, including repeatability, reproducibility, calibration control, and measurement process documentation, is a plus.&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;3&quot;&gt;Able to work independently with limited direction while maintaining strong alignment with project goals and cross-functional priorities.&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;3&quot;&gt;Collaborative and effective in a multidisciplinary engineering environment spanning photonics, electronics, packaging, manufacturing, test, firmware, and system validation.&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;3&quot;&gt;Strong project planning and execution skills, including the ability to manage priorities, track progress, and deliver high-quality results on schedule.&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;3&quot;&gt;Excellent written and verbal communication skills, with the ability to communicate technical results clearly to a range of audiences.&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;3&quot;&gt;Strong critical thinking, analytical, creative, and detail-oriented problem-solving skills.&lt;/li&gt;
&lt;li data-renderer-start-pos=&quot;3&quot;&gt;Comfortable operating in a fast-paced startup environment with evolving requirements and ambitious technical goals.&amp;nbsp;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;PsiQuantum provides equal employment opportunity for all applicants and employees. PsiQuantum does not unlawfully discriminate on the basis of race, color, religion, sex (including pregnancy, childbirth, or related medical conditions), gender identity, gender expression, national origin, ancestry, citizenship, age, physical or mental disability, military or veteran status, marital status, domestic partner status, sexual orientation, genetic information, or any other basis protected by applicable laws.&lt;/p&gt;
&lt;p&gt;&lt;strong data-stringify-type=&quot;bold&quot;&gt;Note: PsiQuantum will only reach out to you using an official PsiQuantum email address and will never ask you for bank account information as part of the interview process. Please report any suspicious activity to &lt;/strong&gt;&lt;strong data-stringify-type=&quot;bold&quot;&gt;&lt;a class=&quot;c-link&quot; href=&quot;mailto:recruiting@psiquantum.com&quot; target=&quot;_blank&quot; data-stringify-link=&quot;mailto:recruiting@psiquantum.com&quot; data-sk=&quot;tooltip_parent&quot;&gt;recruiting@psiquantum.com&lt;/a&gt;&lt;/strong&gt;&lt;strong data-stringify-type=&quot;bold&quot;&gt;.&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;We are not accepting unsolicited resumes from employment agencies.&lt;/p&gt;&lt;div class=&quot;content-pay-transparency&quot;&gt;&lt;div class=&quot;pay-input&quot;&gt;&lt;div class=&quot;description&quot;&gt;&lt;p&gt;The ranges below reflect the target ranges for a new hire base salary. One is for the Bay Area (within 50 miles of HQ, Palo Alto), the second one (if applicable) is for elsewhere in the US (beyond 50 miles of HQ, Palo Alto). If there is only one range, it is for the specific location of where the position will be located.&lt;span class=&quot;Apple-converted-space&quot;&gt;&amp;nbsp;&lt;/span&gt;Actual compensation may vary outside of these ranges and is dependent on various factors including but not limited to a candidate&#39;s qualifications including relevant education and training, competencies, experience, geographic location, and business needs. Base pay is only one part of the total compensation package. Full time roles are eligible for equity and benefits. Base pay is subject to change and may be modified in the future.&lt;/p&gt;&lt;/div&gt;&lt;div class=&quot;title&quot;&gt;U.S. Base Pay Range &lt;/div&gt;&lt;div class=&quot;pay-range&quot;&gt;&lt;span&gt;$110,000&lt;/span&gt;&lt;span class=&quot;divider&quot;&gt;&amp;mdash;&lt;/span&gt;&lt;span&gt;$145,000 USD&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;div class=&quot;pay-input&quot;&gt;&lt;div class=&quot;title&quot;&gt;Bay Area Pay Range &lt;/div&gt;&lt;div class=&quot;pay-range&quot;&gt;&lt;span&gt;$152,000&lt;/span&gt;&lt;span class=&quot;divider&quot;&gt;&amp;mdash;&lt;/span&gt;&lt;span&gt;$175,000 USD&lt;/span&gt;&lt;/div&gt;&lt;/div&gt;&lt;/div&gt;

protagonist-levitate:greenhouse:52092440.descriptionHtml:
&lt;p&gt;At Levitate, we’re on a mission to make a real impact for our customers, our team, and the world around us. We believe the best work comes from people who are curious, driven, and excited to grow. Our five core values guide everything we do, and we look for teammates who embody the traits that make those values come to life:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Creating&amp;nbsp;Magic&amp;nbsp;✨&amp;nbsp;You&amp;nbsp;have&amp;nbsp;the&amp;nbsp;&lt;em&gt;persistence&amp;nbsp;&lt;/em&gt;and&amp;nbsp;&lt;em&gt;grit&amp;nbsp;&lt;/em&gt;to&amp;nbsp;turn&amp;nbsp;ambitious&amp;nbsp;ideas&amp;nbsp;into&amp;nbsp;remarkable&amp;nbsp;outcomes.&lt;/li&gt;
&lt;li&gt;Showing&amp;nbsp;Customer&amp;nbsp;Empathy&amp;nbsp;❤️&amp;nbsp;You&amp;nbsp;bring&amp;nbsp;&lt;em&gt;humble&amp;nbsp;confidence&lt;/em&gt;,&amp;nbsp;listening&amp;nbsp;deeply,&amp;nbsp;and&amp;nbsp;putting&amp;nbsp;customers&amp;nbsp;first.&lt;/li&gt;
&lt;li&gt;Making&amp;nbsp;Data-Driven&amp;nbsp;Decisions&amp;nbsp;📊&amp;nbsp;You&amp;nbsp;pair&lt;em&gt;&amp;nbsp;creativity&lt;/em&gt;&amp;nbsp;with&amp;nbsp;insights&amp;nbsp;to&amp;nbsp;make&amp;nbsp;smarter,&amp;nbsp;faster&amp;nbsp;choices.&lt;/li&gt;
&lt;li&gt;Focusing&amp;nbsp;on&amp;nbsp;Solutions,&amp;nbsp;Not&amp;nbsp;Problems&amp;nbsp;🔍&amp;nbsp;You&amp;nbsp;approach&amp;nbsp;challenges&amp;nbsp;with&amp;nbsp;&lt;em&gt;positivity&lt;/em&gt;&amp;nbsp;and&lt;em&gt;&amp;nbsp;critical&amp;nbsp;thinking&lt;/em&gt;,&amp;nbsp;always&amp;nbsp;looking&amp;nbsp;for&amp;nbsp;the&amp;nbsp;way&amp;nbsp;forward.&lt;/li&gt;
&lt;li&gt;Making&amp;nbsp;Small&amp;nbsp;Improvements&amp;nbsp;Every&amp;nbsp;Day&amp;nbsp;🌱&amp;nbsp;You&amp;nbsp;embrace&amp;nbsp;&lt;em&gt;coachability&lt;/em&gt;&amp;nbsp;and&amp;nbsp;&lt;em&gt;lean&amp;nbsp;into&amp;nbsp;discomfort&lt;/em&gt;&amp;nbsp;to&amp;nbsp;grow,&amp;nbsp;improve,&amp;nbsp;and&amp;nbsp;drive&amp;nbsp;lasting&amp;nbsp;change.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;Here, you won’t just do a job, you’ll help create meaningful experiences, solve real problems, and shape the future of our company.&lt;/p&gt;
&lt;p&gt;Being a Sales Development Representative (SDR) at Levitate is a very special and important part of our organization. SDRs are our small business clients’ first impression of Levitate and the crucial first point of connection where we identify opportunities to elevate and transform clients’ outreach strategies.&lt;/p&gt;
&lt;p&gt;Our SDRs are hungry for success, eager to learn, and heavily supported through hands-on training as they grow into Account Executives (AE) through our accelerated promotion plan. We pride ourselves on preparing our SDRs for promotion to an AE role within a timeframe of 6-9 months–and our AE organization contains a structured, intuitive career path for employees to grow through.&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;A&amp;nbsp;Day&amp;nbsp;in&amp;nbsp;the&amp;nbsp;Life&amp;nbsp;of&amp;nbsp;a&amp;nbsp;Levitate&amp;nbsp;SDR&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;You’ll&amp;nbsp;focus&amp;nbsp;on&amp;nbsp;outbound&amp;nbsp;prospecting&amp;nbsp;small&amp;nbsp;businesses&amp;nbsp;across&amp;nbsp;the&amp;nbsp;U.S.&amp;nbsp;(130&amp;nbsp;cold&amp;nbsp;calls)&amp;nbsp;with&amp;nbsp;leads&amp;nbsp;that&amp;nbsp;are&amp;nbsp;provided&amp;nbsp;to&amp;nbsp;you&lt;/li&gt;
&lt;li&gt;You&amp;nbsp;will&amp;nbsp;book&amp;nbsp;demos&amp;nbsp;for&amp;nbsp;your&amp;nbsp;Senior&amp;nbsp;Account&amp;nbsp;Executives&amp;nbsp;and&amp;nbsp;ramp&amp;nbsp;up&amp;nbsp;to&amp;nbsp;3&amp;nbsp;demos/day&amp;nbsp;over&amp;nbsp;time&amp;nbsp;and&amp;nbsp;with&amp;nbsp;training&lt;/li&gt;
&lt;li&gt;Your&amp;nbsp;manager&amp;nbsp;will&amp;nbsp;connect&amp;nbsp;with&amp;nbsp;you&amp;nbsp;for&amp;nbsp;1:1&amp;nbsp;coaching&amp;nbsp;that&amp;nbsp;focuses&amp;nbsp;on&amp;nbsp;helping&amp;nbsp;you&amp;nbsp;improve&amp;nbsp;through&amp;nbsp;call&amp;nbsp;reviews,&amp;nbsp;role-playing,&amp;nbsp;and&amp;nbsp;more&lt;/li&gt;
&lt;li&gt;Once&amp;nbsp;prospects&amp;nbsp;are&amp;nbsp;booked,&amp;nbsp;you&amp;nbsp;will&amp;nbsp;reach&amp;nbsp;out&amp;nbsp;and&amp;nbsp;confirm&amp;nbsp;their&amp;nbsp;attendance&amp;nbsp;at&amp;nbsp;their&amp;nbsp;scheduled&amp;nbsp;demo&lt;/li&gt;
&lt;li&gt;You’ll&amp;nbsp;help&amp;nbsp;drive&amp;nbsp;strategic,&amp;nbsp;top-of-the-funnel&amp;nbsp;lead&amp;nbsp;generation&amp;nbsp;through&amp;nbsp;targeted&amp;nbsp;cold-calling&lt;/li&gt;
&lt;li&gt;Through&amp;nbsp;your&amp;nbsp;strong&amp;nbsp;organizational&amp;nbsp;skills,&amp;nbsp;you&amp;nbsp;will&amp;nbsp;consistently&amp;nbsp;update&amp;nbsp;your&amp;nbsp;activities,&amp;nbsp;opportunities,&amp;nbsp;and&amp;nbsp;account&amp;nbsp;information&amp;nbsp;in&amp;nbsp;our&amp;nbsp;CRM&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Our&amp;nbsp;commitment&amp;nbsp;to&amp;nbsp;our&amp;nbsp;staff&amp;nbsp;is&amp;nbsp;showcased&amp;nbsp;not&amp;nbsp;only&amp;nbsp;through&amp;nbsp;our&amp;nbsp;strong&amp;nbsp;company&amp;nbsp;culture,&amp;nbsp;but&amp;nbsp;also&amp;nbsp;through&amp;nbsp;our&amp;nbsp;employee-centric&amp;nbsp;benefits&amp;nbsp;and&amp;nbsp;programs&amp;nbsp;including:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Paid&amp;nbsp;time&amp;nbsp;off&amp;nbsp;and&amp;nbsp;paid&amp;nbsp;provincial&amp;nbsp;holidays&amp;nbsp;to&amp;nbsp;facilitate&amp;nbsp;strong&amp;nbsp;work-life&amp;nbsp;balance&lt;/li&gt;
&lt;li&gt;Paid&amp;nbsp;parental&amp;nbsp;leave&amp;nbsp;that&amp;nbsp;provides&amp;nbsp;employees&amp;nbsp;with&amp;nbsp;support&amp;nbsp;and&amp;nbsp;flexibility&amp;nbsp;as&amp;nbsp;they&amp;nbsp;grow&amp;nbsp;their&amp;nbsp;families&lt;/li&gt;
&lt;li&gt;Extensive&amp;nbsp;benefit&amp;nbsp;options&amp;nbsp;including&amp;nbsp;private&amp;nbsp;pension&amp;nbsp;matching,&amp;nbsp;healthcare&amp;nbsp;benefits,&amp;nbsp;etc.&amp;nbsp;Culture&amp;nbsp;Crew&amp;nbsp;and&amp;nbsp;Emerging&amp;nbsp;Leader&amp;nbsp;programs&amp;nbsp;to&amp;nbsp;foster&amp;nbsp;employee&amp;nbsp;leadership&amp;nbsp;development,&amp;nbsp;inclusivity,&amp;nbsp;and&amp;nbsp;connection&amp;nbsp;through&amp;nbsp;year-round&amp;nbsp;trainings&amp;nbsp;and&amp;nbsp;events&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Qualifications&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Previous&amp;nbsp;cold&amp;nbsp;calling&amp;nbsp;experience&amp;nbsp;a&amp;nbsp;plus,&amp;nbsp;but&amp;nbsp;not&amp;nbsp;required&lt;/li&gt;
&lt;li&gt;Strong&amp;nbsp;desire&amp;nbsp;to&amp;nbsp;succeed&amp;nbsp;and&amp;nbsp;build&amp;nbsp;a&amp;nbsp;career&amp;nbsp;in&amp;nbsp;sales&lt;/li&gt;
&lt;li&gt;Ability&amp;nbsp;to&amp;nbsp;self-motivate&amp;nbsp;and&amp;nbsp;succeed&amp;nbsp;in&amp;nbsp;a&amp;nbsp;fast-paced&amp;nbsp;role&lt;/li&gt;
&lt;li&gt;Willingness&amp;nbsp;to&amp;nbsp;ask&amp;nbsp;for&amp;nbsp;help&amp;nbsp;and&amp;nbsp;an&amp;nbsp;openness&amp;nbsp;to&amp;nbsp;being&amp;nbsp;coached&lt;/li&gt;
&lt;li&gt;Ability&amp;nbsp;to&amp;nbsp;multitask,&amp;nbsp;organize,&amp;nbsp;and&amp;nbsp;prioritize&amp;nbsp;work&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;u&gt;Notices&lt;/u&gt;:&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;AI&lt;/strong&gt;:&amp;nbsp;Levitate&amp;nbsp;will&amp;nbsp;use&amp;nbsp;Artificial&amp;nbsp;Intelligence-supported&amp;nbsp;tools&amp;nbsp;to&amp;nbsp;screen,&amp;nbsp;assess&amp;nbsp;or&amp;nbsp;select&amp;nbsp;applicants&amp;nbsp;at&amp;nbsp;one&amp;nbsp;or&amp;nbsp;more&amp;nbsp;stages&amp;nbsp;of&amp;nbsp;the&amp;nbsp;recruitment&amp;nbsp;process&amp;nbsp;for&amp;nbsp;this&amp;nbsp;position.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Compensation&lt;/strong&gt;:&amp;nbsp;Compensation&amp;nbsp;for&amp;nbsp;this&amp;nbsp;position&amp;nbsp;is&amp;nbsp;a&amp;nbsp;$50,000&amp;nbsp;base&amp;nbsp;+&amp;nbsp;$15,000&amp;nbsp;bonus&amp;nbsp;=&amp;nbsp;$65,000&amp;nbsp;CAD&amp;nbsp;on&amp;nbsp;target&amp;nbsp;earnings.&amp;nbsp;The&amp;nbsp;bonus&amp;nbsp;portion&amp;nbsp;is&amp;nbsp;uncapped.&lt;/li&gt;
&lt;li&gt;&lt;strong&gt;Vacancy&amp;nbsp;Status:&amp;nbsp;&lt;/strong&gt;This&amp;nbsp;position&amp;nbsp;is&amp;nbsp;being&amp;nbsp;publicly&amp;nbsp;advertised&amp;nbsp;to&amp;nbsp;support&amp;nbsp;ongoing&amp;nbsp;hiring&amp;nbsp;needs&amp;nbsp;and&amp;nbsp;may&amp;nbsp;be&amp;nbsp;used&amp;nbsp;to&amp;nbsp;fill&amp;nbsp;an&amp;nbsp;existing&amp;nbsp;vacancy&amp;nbsp;or&amp;nbsp;to&amp;nbsp;support&amp;nbsp;anticipated&amp;nbsp;team&amp;nbsp;growth.&amp;nbsp;Depending&amp;nbsp;on&amp;nbsp;business&amp;nbsp;needs&amp;nbsp;at&amp;nbsp;the&amp;nbsp;time&amp;nbsp;of&amp;nbsp;hire,&amp;nbsp;this&amp;nbsp;role&amp;nbsp;may&amp;nbsp;be&amp;nbsp;filled&amp;nbsp;as&amp;nbsp;a&amp;nbsp;backfill&amp;nbsp;or&amp;nbsp;as&amp;nbsp;new&amp;nbsp;headcount.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;

qedinvestors-nubank:greenhouse:7554184.descriptionHtml:
&lt;h3&gt;Principal Engineer, Mobile Platforms&lt;/h3&gt;
&lt;h4&gt;The Opportunity:&lt;/h4&gt;
&lt;p&gt;This position is for an Engineer Principal (IC9) to join the Mobile Platforms BU.&lt;br&gt;&lt;br&gt;Mobile Platforms is the BU responsible for Nubank’s entire mobile foundation: we design, build, and operate the platforms that power the Nubank app across all markets. The BU is organized in three business areas – App Foundations (core architecture, app startup, developer experience), App Enablement (navigation performance, Backend Driven Content/BDC, design system infra &amp;amp; Rosetta), and App Release (CI/CD, release train, observability, app analytics &amp;amp; data). Together, these areas provide the canonical Flutter + BDC architecture, tooling, and guardrails that enable product teams to ship a fast, reliable, and consistent app at global scale.&lt;/p&gt;
&lt;div class=&quot;container ng-tns-c975199164-167 hide&quot;&gt;
&lt;div class=&quot;carousel-container ng-tns-c975199164-167&quot;&gt;
&lt;div class=&quot;carousel-content ng-tns-c975199164-167&quot;&gt;&amp;nbsp;&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;h4&gt;About Nubank&#39;s Engineering Culture:&lt;/h4&gt;
&lt;p&gt;We believe in small, independent teams, a process-light environment, and a culture of trust and collaboration. We made a strategic bet on Flutter and Server-Driven UI not just for technical reasons, but because they empower our engineers to work end-to-end and scale our organization. You will be a key steward and champion of this culture, driving technical decisions that reinforce our principles of autonomy and developer empowerment.&lt;span class=&quot;button-container hide-from-message-actions ng-star-inserted&quot;&gt; &amp;nbsp; &lt;/span&gt;&lt;/p&gt;
&lt;div class=&quot;container ng-tns-c975199164-168 hide&quot;&gt;
&lt;div class=&quot;carousel-container ng-tns-c975199164-168&quot;&gt;
&lt;div class=&quot;carousel-content ng-tns-c975199164-168&quot;&gt;&amp;nbsp;&lt;/div&gt;
&lt;/div&gt;
&lt;/div&gt;
&lt;h4&gt;What we have to offer:&lt;/h4&gt;
&lt;ul&gt;
&lt;li&gt;The opportunity to lead the technical direction of Nubank’s Mobile Platform – the foundational system that underpins the Nubank app for tens of millions of customers across all markets.&lt;/li&gt;
&lt;li&gt;Ownership of multi‑year, high‑visibility initiatives such as Mobile Destination Architecture, native code deprecation, app startup refactor, navigation performance, BDC evolution and App Excellence, with clear impact on company OKRs.&lt;/li&gt;
&lt;li&gt;A uniquely cross‑cutting scope across App Foundations, App Enablement and App Release – spanning architecture, developer experience, CI/CD, observability and data – allowing you to shape how the entire engineering org builds mobile products.&lt;/li&gt;
&lt;li&gt;Space to grow your principal‑level leadership: driving strategy, defining technical roadmaps, sponsoring other senior/principal engineers, and representing Mobile Platforms in cross‑company forums and executive discussions.&lt;/li&gt;
&lt;li&gt;A highly collaborative environment with top mobile, platform and experience design talent, where you will partner closely with Magic App, NuDS, Growth and markets teams to deliver a world‑class, consistent and high‑performance app.&lt;/li&gt;
&lt;/ul&gt;
&lt;h4&gt;Core Qualifications (What We&#39;re Looking For)&lt;/h4&gt;
&lt;ul&gt;
&lt;li&gt;&lt;strong&gt;15+ years&lt;/strong&gt; of software engineering experience, with a proven track record of designing, building, and operating large-scale mobile applications or platforms at an enterprise level.&lt;/li&gt;
&lt;li&gt;Has &lt;strong&gt;deep expertise in mobile architecture&lt;/strong&gt; (Flutter/Dart, native bridges, modularization, mono-repo architectures) and can design end‑to‑end solutions spanning app startup, navigation, state management, and release lifecycle.&lt;/li&gt;
&lt;li&gt;Understands and can evolve &lt;strong&gt;BDC (Backend Driven Content)&lt;/strong&gt; as Nubank’s main server‑driven UI platform, defining how BDC, Flutter and NuDS work together to enable safe, fast iteration without depending on store releases.&lt;/li&gt;
&lt;li&gt;Is capable of &lt;strong&gt;setting the technical vision for the three Mobile Platforms business areas&lt;/strong&gt; (App Foundations, App Enablement, App Release), connecting architecture choices with company‑level goals such as App Excellence, Magic App and Destination Architecture.&lt;/li&gt;
&lt;li&gt;Has a strong track record of &lt;strong&gt;leading large, ambiguous cross‑org initiatives&lt;/strong&gt; – e.g., native‑to‑Flutter/BDC migrations, app startup refactors, navigation performance programs, or observability/analytics redesigns – influencing dozens of squads and multiple BUs.&lt;/li&gt;
&lt;li&gt;Drives &lt;strong&gt;platform engineering at scale&lt;/strong&gt;: defines canonical patterns, RFCs and reference implementations; creates reusable tools/libraries; and ensures that internal customers can adopt the platform with low friction and high quality.&lt;/li&gt;
&lt;li&gt;Is comfortable &lt;strong&gt;leading through influence&lt;/strong&gt;: aligning PMs, EMs, Staff/Principal engineers and leadership on trade‑offs (performance vs. flexibility, platform vs. product), and making tough calls grounded in data, risk and long‑term sustainability.&lt;/li&gt;
&lt;li&gt;Invests heavily in &lt;strong&gt;technical leadership and mentorship&lt;/strong&gt;, raising the bar for senior engineers across Mobile Platforms and product BUs, and building a strong culture around architecture reviews, design docs, and post‑incident learning.&lt;/li&gt;
&lt;li&gt;Cares deeply about &lt;strong&gt;observability, reliability and release health&lt;/strong&gt; for mobile: tying together app metrics (startup, TTFD, crashes, jank), CI/CD, feature rollout (BDC + app releases) and on‑call practices into a coherent strategy.&lt;/li&gt;
&lt;li&gt;Is motivated by working on a &lt;strong&gt;horizontal, high‑impact platform&lt;/strong&gt; that directly shapes how every experience in the Nubank app is built, released and monitored, across Brazil, Mexico, Colombia and future markets.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;br&gt;If you feel interested in these challenges and want to work on a very engaged and talented team, this is the place for you!&lt;br&gt;&lt;br&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;

qumracapital-appsflyer:greenhouse:855871.descriptionHtml:
&lt;p&gt;AppsFlyer helps brands make good choices for their business and their customers with its advanced measurement, data analytics, deep linking, engagement, fraud protection, data clean room, and privacy-preserving technologies. Built on the idea that brands can increase customer privacy while providing exceptional experiences, AppsFlyer empowers thousands of creators and 10,000+ technology partners to create better, more meaningful customer relationships.&lt;/p&gt;
&lt;p&gt;We’re looking for a Senior Customer Success Manager to join our New York City or San Francisco offices and support a portfolio of Enterprise customers in North America. This is a high-ownership role focused on driving measurable customer value, retention, and growth through product adoption, technical solution design, and partnership with sales.&lt;/p&gt;
&lt;p&gt;As a Senior CSM, you act as both a strategic advisor and a technical partner to your customers, translating complex business objectives into actionable technical roadmaps and product adoption plans. You’ll work at the intersection of customer strategy and technical execution — leading solution design, driving implementation planning, and ensuring customers realize the full value of AppsFlyer’s platform. You’ll also contribute to the success of the broader Customer Success team. Our CS culture is customer‑obsessed and results‑driven. We coach for impact, operate with rigor, and influence at scale across Sales, Product, and Marketing.&lt;/p&gt;
&lt;h3&gt;&lt;strong&gt;What You’ll Do:&lt;/strong&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;Client Value Realization: drive customer outcomes and product adoption across your portfolio of customers. Partner with Sales to mitigate client risk and run expansion motions across strategic Enterprise customer segments, leading to improved Gross Revenue Retention and Net Revenue Retention.&lt;/li&gt;
&lt;li&gt;Ability to travel 33% onsite to customers and key internal onsites.&lt;/li&gt;
&lt;li&gt;Co-own the post-sales relationship, in conjunction with your sales partner, for a portfolio of customers focused in North America to drive retention and growth.&lt;/li&gt;
&lt;li&gt;Lead onboarding, training, and enablement sessions, translating complex AppsFlyer products and data concepts into clear, actionable outcomes for customers.&lt;/li&gt;
&lt;li&gt;Develop and maintain long-term technical roadmaps for your accounts by translating client business objectives into key project deliverables, technical milestones, and product adoption plans to ensure clearly defined requirements and timelines aligned with key technical stakeholders.&lt;/li&gt;
&lt;li&gt;Lead solution design for complex customer use cases, including scoping custom integrations and product configurations in collaboration with Product and Engineering teams to drive measurable value realization.&lt;/li&gt;
&lt;li&gt;Conduct regular check-ins, usage reviews, and strategic syncs to ensure engagement and satisfaction.&lt;/li&gt;
&lt;li&gt;Run Executive Business Reviews (EBRs) with senior and technical customer stakeholders to showcase impact and align on goals; leverage effective data storytelling to communicate AppsFlyer value&lt;/li&gt;
&lt;li&gt;Act as a growth partner by understanding customers’ business goals and analyzing customer data to surface insights, identify mutual growth opportunities, and recommend optimizations to drive measurable value realization.&lt;/li&gt;
&lt;li&gt;Capture feedback and work closely with Product, R&amp;amp;D, and Support teams to drive improvements. Influence the product roadmap through data-backed client use cases and direct collaboration with Product Strategy and Product Team Leaders.&lt;/li&gt;
&lt;li&gt;Actively support renewal conversations and identify opportunities for feature adoption or account expansion. Co-identify Customer Success Qualified Leads (CSQLs) and partner with AMs on follow-through.&lt;/li&gt;
&lt;li&gt;Lead customer issue management by proactively identifying risks, coordinating cross-functional resources, and driving issues through to resolution. Create red flag action plans and collaborate with cross-functional teams to improve customer value realization.&lt;/li&gt;
&lt;li&gt;Collaborate with internal teams, including Sales, Product, Support, and Solutions Architecture, to deliver customer outcomes.&lt;/li&gt;
&lt;li&gt;Act as a mentor and force-multiplier for other CSMs by sharing best practices, hosting internal trainings, coaching new hires, and contributing to team initiatives.&lt;/li&gt;
&lt;/ul&gt;
&lt;h3&gt;&lt;strong&gt;What you have:&lt;/strong&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;7+ years of experience in Customer Success, Technical Account Management, Solutions Engineering, or a technical client-facing SaaS role, ideally in mobile, ad tech, or martech.&lt;/li&gt;
&lt;li&gt;Proven ability to manage complex customer relationships and influence retention and growth outcomes, with a strong track record of building and executing technical roadmaps and project plans.&lt;/li&gt;
&lt;li&gt;Strong communication skills with executive, technical, and business audiences — including the ability to translate technical concepts into business value and deliver effective data storytelling.&lt;/li&gt;
&lt;li&gt;Act as an analytical thinker. Comfortable working with data and turning insights into action. Hands-on experience with data analysis and business intelligence tools (e.g., SQL, Athena, BigQuery, Looker, or similar) to extract insights, diagnose issues, and communicate business impact.&lt;/li&gt;
&lt;li&gt;Experienced in leveraging discovery frameworks to qualify and validate customer problems to properly scope, design, guide and deliver on technical solutions, including complex integrations, product troubleshooting, and custom implementations in partnership with Product and Engineering teams.&lt;/li&gt;
&lt;li&gt;Proactive and solutions-driven with high autonomy, ownership, and ability to operate in ambiguity.&lt;/li&gt;
&lt;li&gt;Comfortable working in a fast-paced, multicultural, and evolving environment.&lt;/li&gt;
&lt;li&gt;Demonstrated ability to leverage AI tools (e.g., ChatGPT, Claude) to drive efficiency and scale across customer-facing workflows — from account research and data synthesis to communication and strategic planning.&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&lt;strong&gt;Bonus Qualifications:&lt;/strong&gt;&lt;/p&gt;
&lt;ul&gt;
&lt;li&gt;Industry experience within SaaS marketing / remarketing technologies, attribution, data integrations, and/or digital advertising in a mobile and/or omnichannel ecosystem.&lt;/li&gt;
&lt;li&gt;Proficiency in at least one programming or scripting language (e.g., Python, JavaScript, SQL) and experience with SDK and APIs.&amp;nbsp;&lt;/li&gt;
&lt;li&gt;Experience leading product beta programs, co-designing with product teams, and developing repeatable playbooks for product rollouts.&lt;br&gt;&lt;br&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;This role is based in our New York office and requires in-office presence of a three days per week.&amp;nbsp;&lt;/p&gt;
&lt;p&gt;For our US-based candidates, the expected On Target Earnings (OTE) range from $165,000 to $180,000 (including bonus or commission). The offer varies on many factors, including market location, job-related knowledge, skills, experience, interview results, references, etc.&lt;/p&gt;
&lt;p&gt;As a global company operating from 25 offices across 19 countries, we reflect the human mosaic of the diverse and multicultural world in which we live. We ensure equal opportunities for all of our employees and promote the recruitment of diverse talents to our global teams without consideration of race, gender, culture, or sexual orientation. We value and encourage curiosity, diversity, and innovation from all our employees, customers, and partners.&lt;/p&gt;
&lt;p&gt;&lt;a class=&quot;c-link&quot; href=&quot;https://www.appsflyer.com/blog/how-all-in-shaped-our-story-and-could-define-your-career/&quot; target=&quot;_blank&quot; data-stringify-link=&quot;https://www.appsflyer.com/blog/how-all-in-shaped-our-story-and-could-define-your-career/&quot; data-sk=&quot;tooltip_parent&quot;&gt;“As a Customer Obsessed company, we must first be Employee Obsessed. We need to make sure that we provide the team with the tools and resources they need to go All-In.”&lt;/a&gt;&amp;nbsp;Oren Kaniel, CEO&lt;/p&gt;

qumracapital-connecteam:greenhouse:60062.descriptionHtml:
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;Who Connecteam is:&lt;/strong&gt;&lt;/p&gt;
&lt;p&gt;Connecteam is the leading platform for managing deskless teams, trusted by over 80,000 businesses worldwide.&lt;/p&gt;
&lt;p&gt;We built Connecteam for real operators - the people running shifts, jobs, and teams across stores and sites. The kind of work that doesn’t happen behind a desk, and doesn’t have time for messy spreadsheets, scattered group chats, or tools that don’t talk to each other.&lt;/p&gt;
&lt;p&gt;Connecteam brings daily operations and team communication into one intuitive app - from hiring and scheduling to training, tasks, and day-to-day coordination. It gives teams the clarity and control to run the day, shift after shift, job after job.&lt;/p&gt;
&lt;p&gt;Backed by $220M+ from Insights Partners, Stripes, and Tiger Global, Connecteam is rapidly expanding worldwide - empowering frontline teams to work smarter, stay connected, and operate with greater efficiency.&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&lt;strong&gt;About the role&lt;/strong&gt;&lt;strong&gt;&lt;br&gt;&lt;/strong&gt; Connecteam is looking for a driven and hands-on Mid-Market Sales Team Lead to manage and grow a team of Account Executives focused on Mid-Market &amp;amp; Enterprise customers. This leader will coach reps through complex sales cycles, drive pipeline generation and conversion, and help scale a high-performing sales culture in a fast-growing SaaS environment focused on deskless and frontline workforce management. Connecteam serves businesses across industries, including construction, retail, hospitality, healthcare, manufacturing, and field services.&lt;/p&gt;
&lt;h1&gt;&lt;strong&gt;Key Responsibilities&lt;/strong&gt;&lt;/h1&gt;
&lt;ul&gt;
&lt;li&gt;Lead, mentor, manage, and develop a team of Mid-Market Account Executives&lt;/li&gt;
&lt;li&gt;Drive pipeline growth, forecasting accuracy, and quota attainment&lt;/li&gt;
&lt;li&gt;Improve sales processes, methodologies, and performance metrics&lt;/li&gt;
&lt;li&gt;Coach reps on discovery, demos, negotiation, and closing&lt;/li&gt;
&lt;li&gt;Collaborate with Marketing, SDRs, RevOps, and Customer Success&lt;/li&gt;
&lt;li&gt;Hire, onboard, and ramp new sales talent&lt;/li&gt;
&lt;li&gt;Analyze KPIs and optimize team performance in a high-growth SaaS environment&lt;/li&gt;
&lt;/ul&gt;
&lt;h1&gt;&lt;strong&gt;Experience &amp;amp; Skills&lt;/strong&gt;&lt;/h1&gt;
&lt;ul&gt;
&lt;li&gt;3+ years managing SaaS sales teams (preferably Mid-Market)&lt;/li&gt;
&lt;li&gt;Strong background in B2B SaaS sales&lt;/li&gt;
&lt;li&gt;Experience managing high-velocity and consultative sales cycles&lt;/li&gt;
&lt;li&gt;Proven success leading quota-achieving teams&lt;/li&gt;
&lt;li&gt;Excellent coaching, forecasting, and pipeline management skills&lt;/li&gt;
&lt;li&gt;Advantage: experience selling to operations/frontline/workforce management industries&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;#LI-Remote&lt;/p&gt;&lt;div class=&quot;content-conclusion&quot;&gt;&lt;h2&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Joining Connecteam Is The Smart Move:&lt;/span&gt;&lt;/h2&gt;
&lt;ul&gt;
&lt;li style=&quot;font-weight: 400;&quot;&gt;&lt;strong&gt;We build our people up.&lt;/strong&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt; Every team member is treated as a long-term investment and we recognize the value in always nurturing and training them so they can go above and beyond in their skills and job duties.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-weight: 400;&quot;&gt;&lt;strong&gt;We make an impact on our customer’s business. &lt;/strong&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;We are on a mission to provide managers of all business types and sizes with the tools they need to communicate, operate, engage, and run their deskless workforce. Our product offers them an effective and affordable solution to run their business.&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-weight: 400;&quot;&gt;&lt;strong&gt;We get the job done. &lt;/strong&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Connecteam employees are passionate in executing their job duties so they can drive the company forward and provide real value to our customers.&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-weight: 400;&quot;&gt;&lt;strong&gt;We have fun! &lt;/strong&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;From weekly happy hours to holiday parties, we always enjoy each other’s company (and good food, of course). Connecteam is like one big, happy family!&lt;/span&gt;&lt;/li&gt;
&lt;li style=&quot;font-weight: 400;&quot;&gt;&lt;strong&gt;Everyone is welcome. &lt;/strong&gt;&lt;span style=&quot;font-weight: 400;&quot;&gt;Connecteam is committed to building an encouraging, caring, and supportive environment. We share a responsibility to support our team and enrich their lives.&amp;nbsp;&lt;/span&gt;&lt;/li&gt;
&lt;/ul&gt;
&lt;h2&gt;&lt;strong&gt;Together we will shape the future of work!&lt;/strong&gt;&lt;/h2&gt;
&lt;p&gt;&lt;strong&gt;&lt;a href=&quot;https://drive.google.com/file/d/1JivAppdCXE5QjtK_uWM9ue2834blvyfC/view?usp=sharing&quot; target=&quot;_blank&quot;&gt;Our privacy policy &lt;/a&gt;&lt;/strong&gt;&lt;/p&gt;&lt;/div&gt;

remotely-bridgebio:greenhouse:5142397007.descriptionHtml:
&lt;div class=&quot;content-intro&quot;&gt;&lt;p&gt;&lt;span style=&quot;text-decoration: underline;&quot;&gt;&lt;strong&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Mavericks Wanted&lt;/span&gt;&lt;/strong&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/span&gt;&lt;/p&gt;
&lt;p&gt;&lt;span data-contrast=&quot;auto&quot;&gt;When was the last time you achieved the impossible? If that thought feels overwhelming, you might want to pause here, but if it sparks excitement...read on&lt;/span&gt;&amp;nbsp;&lt;br&gt;&lt;span data-contrast=&quot;auto&quot;&gt; &lt;/span&gt;&amp;nbsp;&lt;br&gt;&lt;span data-contrast=&quot;auto&quot;&gt;In 2015, we pioneered a “moneyball for biotech” approach, pooling projects and promising early-stage research from academia together under one financial umbrella to reduce risk and unleash innovation. This model allows science and small teams of experts to lead the way. We build bridges to groundbreaking advancements in rare&amp;nbsp;disease, and&amp;nbsp;develop life-changing medicines for patients with unmet needs as fast as humanly possible. &lt;/span&gt;&amp;nbsp;&lt;br&gt;&lt;span data-contrast=&quot;auto&quot;&gt; &lt;/span&gt;&amp;nbsp;&lt;br&gt;&lt;span data-contrast=&quot;auto&quot;&gt;Together we define white space, push boundaries, and empower people to solve problems. If you&#39;re someone who defies convention, join us and work alongside some of the most respected minds in the industry. Together, we&#39;ll&amp;nbsp;ask&amp;nbsp;&quot;why not?&quot; and help reengineer the future of biopharma. At BridgeBio, we value curiosity and experimentation—including the ethical &amp;amp; thoughtful use of AI to improve clarity, speed, and quality of work.&lt;/span&gt;&lt;span data-ccp-props=&quot;{&amp;quot;134233117&amp;quot;:true,&amp;quot;134233118&amp;quot;:true,&amp;quot;201341983&amp;quot;:0,&amp;quot;335559740&amp;quot;:240}&quot;&gt;&amp;nbsp;&lt;/span&gt;&lt;/p&gt;&lt;/div&gt;&lt;h3&gt;&lt;u&gt;What You&#39;ll Do&lt;/u&gt;&lt;/h3&gt;
&lt;p&gt;Lead CMC regulatory strategy and execution across development and post-approval programs, ensuring high-quality submissions aligned with global regulatory requirements. Serve as a strategic Regulatory CMC subject-matter expert and key cross-functional partner, influencing regulatory decision-making and program execution. This role is primarily an individual contributor position with the opportunity to mentor, coach, and potentially manage team members as organizational needs evolve. The ideal candidate brings deep Regulatory CMC expertise, strong cross-functional leadership skills, demonstrated experience with global and ROW filings (e.g., MENA, LATAM, APAC), and practical fluency leveraging AI-enabled and digital tools to improve regulatory workflows and deliverables.&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;h3&gt;&lt;u&gt;Responsibilities&lt;/u&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;Lead CMC regulatory strategy, planning, and execution for IND/CTA, NDA/MAA, post-approval submissions, and global registrations across development programs&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Partner closely with CMC, Quality, Regulatory Operations, and cross-functional stakeholders to ensure timely, high-quality regulatory submissions aligned with global health authority expectations&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Provide strategic guidance on CMC regulatory risks, change controls, health authority interactions, and submission strategies to support program objectives and regulatory compliance&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Coordinate and review responses to CMC-related health authority requests and ensure regulatory conformance of technical documentation, manufacturing information, validation activities, and labeling content&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Mentor and coach junior team members and provide oversight for vendors and/or assigned staff, including prioritization, feedback, and support for development activities&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Apply AI-enabled tools and digital technologies to improve the efficiency, quality, and consistency of regulatory deliverables while adhering to company policies and data governance standards&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Contribute to global regulatory activities, including demonstrated experience supporting Rest of World (ROW) submissions (e.g., MENA, LATAM, APAC) and coordinating regional filing requirements and strategies&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;h3&gt;&lt;u&gt;Where You&#39;ll Work&lt;/u&gt;&lt;/h3&gt;
&lt;p&gt;&amp;nbsp;&lt;em&gt;This is a U.S.-based remote role that will require quarterly, or as needed visits to our San Francisco Office.&lt;/em&gt;&lt;/p&gt;
&lt;p&gt;&amp;nbsp;&lt;/p&gt;
&lt;h3&gt;&lt;u&gt;Who You Are&lt;/u&gt;&lt;/h3&gt;
&lt;ul&gt;
&lt;li&gt;
&lt;p&gt;BA/BS degree in Chemistry, Pharmaceutical Sciences, Life Sciences, or related scientific discipline required; advanced degree preferred&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Extensive Regulatory Affairs CMC experience within the biotechnology and/or pharmaceutical industry, including successful support of NDA/MAA submissions for new chemical entities in pre- and post-approval environments&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Demonstrated experience leading complex global regulatory submissions, including Rest of World (ROW) regions (e.g., MENA, LATAM, APAC), with ability to navigate regional regulatory requirements and coordinate cross-regional filing strategies&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Strong knowledge of global health authority regulations, CMC development, manufacturing processes, and Quality documentation standards, with the ability to apply regulatory strategy in complex development environments&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Proven ability to lead through influence in a matrixed organization, including strong cross-functional collaboration, strategic thinking, project management, communication, and problem-solving skills&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Demonstrated experience mentoring, coaching, and developing others; prior direct people management experience preferred but not required&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Demonstrated experience utilizing AI-enabled or digital tools to improve efficiency, quality, or decision-making in regulatory or technical workflows while maintaining compliance with company policies and data governance standards&lt;/p&gt;
&lt;/li&gt;
&lt;li&gt;
&lt;p&gt;Ability to travel as needed (approximately 10–20%) to support business and regulatory activities&lt;/p&gt;
&lt;/li&gt;
&lt;/ul&gt;&lt;div class=&quot;content-pay-transparency&quot;&gt;&lt;div class=&quot;pay-input&quot;&gt;&lt;div class=&quot;description&quot;&gt;&lt;div&gt;
